MODEL_WORDS=r'\b(?:[a-z]+[A-Z][A-Za-z0-9_-]+|[A-Z]{2,}[a-z][A-Za-z0-9_-]+|[A-Z][A-Z0-9]+-[A-Za-z0-9-]+)\b'
def clean(t):return re.sub(r'\s+',' ',str(t or '')).strip()
def sentences(t):
 # Decimal numbers and common dataset abbreviations remain intact.
 return [clean(v) for v in re.split(r'(?<=[.!?])\s+(?=[A-Z])',clean(t)) if clean(v)]
def role(t):
 lo=t.lower();roles=[]
 for regex,label in [(r'pre.?train','pretraining'),(r'\btrain|develop|discovery','development'),(r'external|independent|held.out|test set','independent evaluation'),(r'validat','validation'),(r'prospective','prospective collection/evaluation'),(r'retrospective','retrospective analysis'),(r'synthesi[sz]|experiment|screen|assay','laboratory screen/experiment'),(r'simulat|synthetic','simulation/synthetic data'),(r'patient|participant|cohort|clinical','clinical study population')]:
  if re.search(regex,lo):roles.append(label)
 return '; '.join(roles) or 'reported study/benchmark units'
def locator(sec,sent,off):return {'section':sec,'character_offset':off,'sentence_sha256':hashlib.sha256(sent.encode()).hexdigest()[:16]}
def source_url(src,label,base):return src.get('section_urls',{}).get(label,base+'#'+({'Abstract':'Abs1','Methods':'SecMethods','Results':'SecResults','Data availability':'data-availability','Code availability':'code-availability'}.get(label,label.lower().replace(' ','-'))))
def sources(p):
 path=ROOT/'research-cache'/(p['id']+'-source.json');s=json.loads(path.read_text()) if path.exists() else {};sec=s.get('sections',{});texts={'Abstract':clean(s.get('abstract') or p.get('abstract') or p.get('epmc_abstract'))}
 for k in ['Methods','Results','Results and discussion','Discussion','Data availability','Code availability']:
  if sec.get(k):texts[k]=clean(sec[k])
 # Early-release official PDFs contain the actual main manuscript even when publisher HTML is abstract-only.
 for suffix,label in [('.txt','Full manuscript PDF'),('-author.txt','Author-hosted manuscript PDF'),('-pmc.txt','PubMed Central full manuscript')]:
  f=ROOT/'research-cache'/(p['id']+suffix)
  if f.exists() and len(texts.get('Methods',''))<100:
   raw=f.read_text(errors='replace');raw=re.split(r'\nReferences\s*\n',raw)[0];texts[label]=clean(raw)
 return s,texts

def fact_counts(p,src,texts):
 values=[];seen=set();base=p['url']
 if any(v in p.get('article_type','').lower() for v in ['review','protocol']):return values
 # Abstract quantities are separately attributed; detailed-method quantities never silently become the headline total.
 for section in ['Abstract','Methods','Results']:
  txt=texts.get(section,'');budget=12 if section=='Abstract' else 4
  if not txt:continue
  for sent in sentences(txt):
   if re.search(r'catalog|catalogue|Cat\.|manufactur|\brefs?\b|references|reagent|vendor',sent,re.I) and section!='Abstract':continue
   matches=list(re.finditer(COUNT,sent,re.I))
   for a in matches:
    value=a.group('value').replace(',','').strip();unit=a.group('unit').lower();key=(value,unit,role(sent))
    if section!='Abstract':
     if unit not in ['patients','participants','individuals','subjects','women','children','adolescents','adults','fetuses','donors','cases','controls','admissions','visits','clinical records','health records','samples','specimens','images','slides','whole-slide images','datasets','cohorts','clinical questions','questions','vignettes']:continue
     if not re.search(r'cohort|dataset|train|evaluat|validat|includ|recruit|patient|collect|obtained|access|download|sampled',sent,re.I):continue
     if re.search(r'per well|seeded|plated|passage|tube|reagent|antibod|purif|stain|incubat|centrifug|ref|et al',sent,re.I):continue
    if key in seen:continue
    if len(value)>12 or re.fullmatch(r'\d{4}',value) and 1900<=int(value)<=2030 and unit in ['trials','studies']:continue
    seen.add(key);ds=list(dict.fromkeys(re.findall(r'(?<![A-Za-z0-9])(?:'+DATA_NAMES+r')(?![A-Za-z0-9])',sent)))[:3];r=role(sent)
    context=f'{r}; '+('dataset: '+', '.join(ds)+'; ' if ds else '')+f'quantity reported in {section}. Counts across roles can overlap.'
    values.append({'value':value,'unit':unit,'bound':clean(a.group('bound')) or 'as reported','context':context,'cohort_role':r,'source_section':section,'evidence_url':source_url(src,section,base) if 'PDF' not in section else base,'verification':'source_extracted_count','evidence_locator':locator(section,sent,txt.find(sent))})
    budget-=1
    if budget<=0:break
   if budget<=0:break
 return values

def quantitative(p,s,texts):
 out=[]
 patterns=[('AUROC/AUC',r'\b(?:AUROC|AUC|area under (?:the )?(?:receiver operating characteristic )?curve)\s*(?:of|=|:)?\s*(\d+(?:\.\d+)?(?:\s*[–-]\s*\d+(?:\.\d+)?)?\s*%?)'),('accuracy',r'\baccuracy\s*(?:of|=|:)?\s*(\d+(?:\.\d+)?\s*%)'),('sensitivity',r'\bsensitivity\s*(?:of|=|:)?\s*(\d+(?:\.\d+)?\s*%)'),('specificity',r'\bspecificity\s*(?:of|=|:)?\s*(\d+(?:\.\d+)?\s*%)'),('mean absolute error',r'\b(?:mean absolute error|MAE)\s*(?:of|=|:)?\s*(\d+(?:\.\d+)?(?:\s*(?:years|days|hours))?)')]
 txt=texts.get('Abstract','')
 for label,pat in patterns:
  for m in list(re.finditer(pat,txt,re.I))[:3]:
   val=m.group(1).strip()
   if not val or val=='.':continue
   sen=next((v for v in sentences(txt) if m.group(0) in v),m.group(0));out.append({'metric':label,'value':val,'endpoint_context':p.get('research_problem') or p['title'],'source_section':'Abstract','evidence_url':source_url(s,'Abstract',p['url']),'verification':'source_extracted_metric','evidence_locator':locator('Abstract',sen,txt.find(sen))})
 return out

def data_profile(p,s,texts):
 names=[]
 for d in p.get('datasets',[]):
  if d.get('name'):names.append(d['name'])
 context=' '.join(texts.get(k,'') for k in ['Abstract','Methods','Data availability','Full manuscript PDF','Author-hosted manuscript PDF'])
 names.extend(re.findall(r'(?<![A-Za-z0-9])(?:'+DATA_NAMES+r')(?![A-Za-z0-9])',context));names.extend(re.findall(ACCESSIONS,context))
 seen=set();names=[n for n in names if not(n.casefold() in seen or seen.add(n.casefold()))][:28]
 av=texts.get('Data availability','');low=av.lower();status=[]
 if re.search(r'request|restricted|controlled|approval|application|agreement|cannot.*public|not publicly|not.*publicly',low):status.append('Some data require application, agreement or author request')
 if re.search(r'public|open.access|freely|available at|deposited|download',low):status.append('Repository or public-resource links are reported')
 if not status:status=['See the original availability statement for item-specific access conditions'] if av else ['No standalone data-availability text was accessible in the inspected source']
 links=[]
 for q in s.get('data_links',[]):
  if q.get('url') and not re.search(r'#(?:ref-|Fig|Tab)',q['url']) and '/figures/' not in q['url'] and '/tables/' not in q['url']:links.append(q['url'])
 links=list(dict.fromkeys((v.get('url') if isinstance(v,dict) else v) for v in p.get('data_urls',[])+links if v));out=[]
 for n in names:
  url=next((u for u in links if re.sub(r'\W','',n).lower() in re.sub(r'\W','',u).lower()),None)
  if not url:
   if re.fullmatch(r'GS[EM]\d+',n):url='https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc='+n
   elif re.fullmatch(r'PRJNA\d+',n):url='https://www.ncbi.nlm.nih.gov/bioproject/'+n
   elif re.fullmatch(r'PXD\d+',n):url='https://www.ebi.ac.uk/pride/archive/projects/'+n
   elif re.fullmatch(r'MSV\d+',n):url=s.get('section_urls',{}).get('Data availability',p['url'])
   elif re.fullmatch(r'E-MTAB-\d+',n):url='https://www.ebi.ac.uk/biostudies/arrayexpress/studies/'+n
   elif re.fullmatch(r'S-BIAD\d+',n):url='https://www.ebi.ac.uk/biostudies/bioimages/studies/'+n
   else:url=s.get('section_urls',{}).get('Data availability',p['url'])
  out.append({'name':n,'source':'Original abstract, methods or availability statement','access':'; '.join(status),'url':url,'verification':'source_extracted_identifier' if re.search(ACCESSIONS,n) else 'source_named_resource','evidence_url':s.get('section_urls',{}).get('Data availability',source_url(s,'Abstract',p['url']))})
 return out,{'summary':'; '.join(status),'evidence_url':s.get('section_urls',{}).get('Data availability',p['url']),'links':links,'source_section_accessible':bool(av),'verification':'source_availability_rules; item-level permissions are not inferred'}

def caveats(p,texts):
 # Existing narrative caveats are own paraphrases. Additional design boundaries are conditioned on actual source language.
 existing=[v for v in sentences(p.get('study_summary','')) if re.search(r'not |rather than|cannot|remain|exploratory|preclinical|small|requiring|requi[res]+|independent|retrospective',v,re.I)]
 if existing:return existing[-2:]
 t=texts.get('Abstract','');lo=t.lower();out=[]
 if 'review' in p.get('article_type','').lower():out.append('Evidence synthesis for '+p['research_problem'].rstrip('.')+'; cited study sizes are not a newly enrolled or pooled population.')
 if 'retrospective' in lo:out.append('Retrospective evidence for '+p['research_problem'].rstrip('.')+'; predictive associations do not establish the effect of using the model in care.')
 if re.search(r'mouse|mice|murine|rat |pig |swine|in vitro|cell.line|cell cultures',lo):out.append('Reported validation includes preclinical or cellular systems for '+p['research_problem'].rstrip('.')+'; human efficacy is not established by those experiments.')
 if re.search(r'synthetic|simulat',lo):out.append('Synthetic/simulation evidence contributes to '+p['research_problem'].rstrip('.')+'; simulated units must remain distinct from observed participants or experiments.')
 if re.search(r'vignette|benchmark|question.answer|reader study|multireader',lo):out.append('The evaluated endpoint concerns case/benchmark or observer performance for '+p['research_problem'].rstrip('.')+'; it is separate from patient health outcomes.')
 if not out:
  out.append('The verified endpoint is '+p.get('study_summary','').split('.')[0].rstrip('.')+'. Claims should remain within the reported evaluation setting and data access conditions.')
 return out[:2]

def main():
 other=json.loads((ROOT/'data/reviews/other.json').read_text());root=json.loads((ROOT/'data/reviews/root.json').read_text());papers={p['id']:p for p in other+root};profiles=[]
 for ident,p0 in papers.items():
  p=dict(p0);s,texts=sources(p);manual=NOTES.get(ident)
  if manual:
   question,method,finding,limit=manual;p.update(research_problem=question,ai_method=method,study_summary=finding);limits=[limit]
  else:limits=caveats(p,texts)
  counts=fact_counts(p,s,texts);datasets,availability=data_profile(p,s,texts);ev=list(p.get('evidence_links',[]))
  for label in ['Abstract','Methods','Results','Data availability','Code availability']:
   if label in texts:ev.append({'label':label,'url':source_url(s,label,p['url'])})
  for e in p.get('additional_evidence',[]):
   if e.get('url'):ev.append(e)
  seen=set();ev=[e for e in ev if e.get('url') and not(e['url'] in seen or seen.add(e['url']))]
  original_scale=[{**r,'verification':'existing_manually_recorded_fact'} for r in p.get('experiment_scale',[]) if r.get('unit')!='study design']
  scale=original_scale+counts
  # Deduplicate quantities without collapsing distinct cohort roles.
  sig=set();scale=[z for z in scale if not((str(z.get('value')),z.get('unit'),z.get('context')) in sig or sig.add((str(z.get('value')),z.get('unit'),z.get('context'))))]
  code=list(dict.fromkeys((v.get('url') if isinstance(v,dict) else v) for v in p.get('code_urls',[])+[z['url'] for z in s.get('code_links',[]) if z.get('url') and '#ref-' not in z['url']] if v))
  rec={'id':ident,'doi':p['doi'],'title':p['title'],'research_problem':p.get('research_problem'),'ai_method':p.get('ai_method'),'study_summary':p.get('study_summary'),'experiment_scale':scale,'quantitative_findings':quantitative(p,s,texts),'datasets':datasets,'data_availability':availability,'code_urls':code,'limitations':limits,'evidence_links':ev,'verification':{'narrative':'manual abstract-grounded paraphrase' if manual else 'preserved article-specific manual narrative from prior review','quantities':'reproducibly extracted plus prior manual facts; overlapping units not summed','datasets':'source-named resources and accessions; permissions require linked availability','source_sections_available':list(texts),'fulltext_reviewed_for_narrative':p0.get('review_level')=='fulltext','prior_review_level':p0.get('review_level'),'prior_curation_level':p0.get('curation_level')},'curation_level':'profile_enriched; verification varies by field','field_status':{'research_problem':'manual_paraphrase','ai_method':'manual_paraphrase','study_summary':'manual_paraphrase','experiment_scale':'mixed_manual_and_source_extracted' if original_scale else 'source_extracted' if scale else 'not_reported_in_inspected_sections','datasets':'source_extracted' if datasets else 'not_named_in_inspected_sections','limitations':'manual_source_grounded' if manual else 'prior_narrative_or_design_boundary'},'profile_scope':'biomedical / generalizable biological AI; species and experimental level remain explicit'}
  if not scale:rec['scale_status']='No defensible study-unit count was recovered; review/protocol sizes and performance metrics are not converted into participant counts.'
  profiles.append(rec)
 out=ROOT/'data/enrichment/other-root.json';out.parent.mkdir(exist_ok=True);out.write_text(json.dumps(profiles,ensure_ascii=False,indent=2))
 print(json.dumps({'profiles':len(profiles),'root_narratives_manually_paraphrased':sum(p['id'] in NOTES for p in profiles),'with_scales':sum(bool(p['experiment_scale']) for p in profiles),'with_named_data':sum(bool(p['datasets']) for p in profiles),'with_quantitative_results':sum(bool(p['quantitative_findings']) for p in profiles)}))

