  if not a:continue
  base='https://www.nature.com/articles/'+p['id'];p['experiment_scale']=[{'value':v,'unit':u,'context':c,'verification':'manually_checked_main_manuscript_fact','evidence_url':base,'source_section':'Methods/Results main manuscript'} for v,u,c in a['scale']]
