  if p['id']!='s41467-026-77908-z':p['verification']['source_sections_manually_inspected_for_detail']=['Methods/Results main manuscript']
  p['datasets']=[{'name':n,'source':'Manually inspected original Methods/Results','access':'Consult the linked original Data availability statement for item-specific permissions.','url':p['data_availability']['evidence_url'],'verification':'manually_checked_dataset_or_experimental_system'} for n in a['data']]+p['datasets']
